    "explanation": "Section 100(1) CPC strictly provides that an appeal shall lie to the High Court from every decree passed in appeal by any subordinate court only 'if the High Court is satisfied that the case involves a substantial question of law.'",
    "misconceptionExplanation": "Appellants frequently seek reappreciation of evidence in second appeal, which is barred.",
