  "myth-211": {
    "id": "myth-211",
    "statement": "Review of a judgment under Section 114 and Order XLVII of the CPC is an appeal in disguise allowing complete rehearing of the case.",
    "classification": "false",
    "subject": "Code of Civil Procedure, 1908",
    "difficulty": "beginner",
    "legislation": "Code of Civil Procedure, 1908",
    "section": "Order XLVII Rule 1",
    "subsection": null,
    "explanation": "A review is not an appeal in disguise (Parsion Devi v. Sumitri Devi). It is strictly limited to: (1) discovery of new important evidence not available despite due diligence, (2) mistake or error apparent on the face of the record, or (3) any other sufficient reason analogous thereto.",
    "misconceptionExplanation": "Litigants often apply for review to reargue propositions rejected by the court.",
    "exceptions": "An erroneous decision cannot be corrected in review; that is the domain of appeal.",
    "errorPhrase": "is an appeal in disguise allowing complete rehearing of the case",
    "correction": "is not an appeal and is strictly limited to error apparent on the face of the record",
    "sourceUrl": "https://www.indiacode.nic.in/handle/123456789/2191",
    "verificationDate": "2026-11-22",
    "status": "Verified against authoritative source",
    "applicableLegalDate": "Current Civil Procedure",
    "revisionKeywords": [
      "Review",
      "Section 114",
      "Order XLVII",
      "Error Apparent",
      "Parsion Devi"
    ],
    "oldVsNew": null
  },
